import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"35、【晉】 坤下離上","description":"橫渠易說 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"橫渠易說 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/hengqu/037.md","filePath":"classics/hengqu/037.md"}'),l={name:"classics/hengqu/037.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><h3 id="彖曰-晉-進也。明出地上-順而麗乎大明-柔進而上行-是以康侯用錫馬蕃庶-畫日三接也。" tabindex="-1">彖曰：晉，進也。明出地上，順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，畫日三接也。 <a class="header-anchor" href="#彖曰-晉-進也。明出地上-順而麗乎大明-柔進而上行-是以康侯用錫馬蕃庶-畫日三接也。" aria-label="Permalink to “彖曰：晉，進也。明出地上，順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，畫日三接也。”">​</a></h3><h3 id="象曰-明出地上-晉-君子以自昭明德。" tabindex="-1">象曰：明出地上，晉，君子以自昭明德。 <a class="header-anchor" href="#象曰-明出地上-晉-君子以自昭明德。" aria-label="Permalink to “象曰：明出地上，晉，君子以自昭明德。”">​</a></h3><h3 id="初六-晉如摧如-貞吉罔孚-裕無咎。-象曰-晉如摧如-獨行正也。-裕無咎-未受命也。" tabindex="-1">初六，晉如摧如，貞吉罔孚，裕無咎。 象曰：“晉如摧如”，獨行正也。“裕無咎”，未受命也。 <a class="header-anchor" href="#初六-晉如摧如-貞吉罔孚-裕無咎。-象曰-晉如摧如-獨行正也。-裕無咎-未受命也。" aria-label="Permalink to “初六，晉如摧如，貞吉罔孚，裕無咎。 象曰：“晉如摧如”，獨行正也。“裕無咎”，未受命也。”">​</a></h3><p>居晉之初，正必見摧，故摧如不害於貞吉也。未孚於人，或未見聽，寬以居之乃無咎。然初六有應在四，居下援上，未安其分，故曰“未受命”也。</p><h3 id="六二-晉如愁如-貞吉。受茲介福-於其王母。-象曰-受茲介福-以中正也。" tabindex="-1">六二，晉如愁如，貞吉。受茲介福，於其王母。 象曰：“受茲介福”，以中正也。 <a class="header-anchor" href="#六二-晉如愁如-貞吉。受茲介福-於其王母。-象曰-受茲介福-以中正也。" aria-label="Permalink to “六二，晉如愁如，貞吉。受茲介福，於其王母。 象曰：“受茲介福”，以中正也。”">​</a></h3><p>進而無撓，多失於肆，故愁如乃吉。六五以陰居尊，故稱“王母”，俱以柔中，故受福可必也。</p><h3 id="六三-眾允-悔亡。-象曰-眾允之志-上行也。" tabindex="-1">六三，眾允，悔亡。 象曰：眾允之志，上行也。 <a class="header-anchor" href="#六三-眾允-悔亡。-象曰-眾允之志-上行也。" aria-label="Permalink to “六三，眾允，悔亡。 象曰：眾允之志，上行也。”">​</a></h3><p>上歷九四，不為眾信，則取悔可必，若志應在上，晉為眾允，則悔亡。</p><h3 id="九四-晉如鼫鼠-貞厲。-象曰-鼫鼠貞厲-位不當也。" tabindex="-1">九四，晉如鼫鼠，貞厲。 象曰：“鼫鼠貞厲”，位不當也。 <a class="header-anchor" href="#九四-晉如鼫鼠-貞厲。-象曰-鼫鼠貞厲-位不當也。" aria-label="Permalink to “九四，晉如鼫鼠，貞厲。 象曰：“鼫鼠貞厲”，位不當也。”">​</a></h3><p>鼫鼠為物，貪而畏人，體陽在進，反據陰位，故動止皆失，與六三之義為相反矣。</p><h3 id="六五-悔亡-失得勿恤。往吉-無不利。-象曰-失得勿恤-往有慶也。" tabindex="-1">六五，悔亡，失得勿恤。往吉，無不利。 象曰：“失得勿恤”，往有慶也。 <a class="header-anchor" href="#六五-悔亡-失得勿恤。往吉-無不利。-象曰-失得勿恤-往有慶也。" aria-label="Permalink to “六五，悔亡，失得勿恤。往吉，無不利。 象曰：“失得勿恤”，往有慶也。”">​</a></h3><p>進而遇陽，故失得不恤而吉也。位不當必有悔，獲吉則悔亡。</p><h3 id="上九-晉其角-維用伐邑-厲吉無咎-貞吝。-象曰-維用伐邑-道未光也。" tabindex="-1">上九，晉其角，維用伐邑，厲吉無咎，貞吝。 象曰：“維用伐邑”，道未光也。 <a class="header-anchor" href="#上九-晉其角-維用伐邑-厲吉無咎-貞吝。-象曰-維用伐邑-道未光也。" aria-label="Permalink to “上九，晉其角，維用伐邑，厲吉無咎，貞吝。 象曰：“維用伐邑”，道未光也。”">​</a></h3><p>窮無所往，故曰角。居明之極，其施未光而應尚狹，持此以進，伐邑討叛而已，危而幸吉以得無咎，然終吝道也。無可進而進不已，惟伐邑於內而可矣，如君子則知止也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
